    Behavior.add_member(:suppress_alerts, Smithy::Schema::Shapes::ShapeRef.new(shape: SuppressAlerts, location_name: 'suppressAlerts', traits: {"smithy.api#documentation" => "<p>\n            Suppresses alerts.\n        </p>"}))
