    Behavior.type = Types::Behavior
    BehaviorCriteria.add_member(:comparison_operator, Smithy::Schema::Shapes::ShapeRef.new(shape: ComparisonOperator, location_name: 'comparisonOperator', traits: {"smithy.api#documentation" => "<p>The operator that relates the thing measured (<code>metric</code>) to the criteria \n          (containing a <code>value</code> or <code>statisticalThreshold</code>). Valid operators include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>string-list</code>: <code>in-set</code> and <code>not-in-set</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>number-list</code>: <code>in-set</code> and <code>not-in-set</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ip-address-list</code>: <code>in-cidr-set</code> and <code>not-in-cidr-set</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>number</code>: <code>less-than</code>, <code>less-than-equals</code>, <code>greater-than</code>, and <code>greater-than-equals</code>\n               </p>\n            </li>\n         </ul>"}))
    BehaviorCriteria.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricValue, location_name: 'value', traits: {"smithy.api#documentation" => "<p>The value to be compared with the <code>metric</code>.</p>"}))
    BehaviorCriteria.add_member(:duration_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationSeconds, location_name: 'durationSeconds', traits: {"smithy.api#documentation" => "<p>Use this to specify the time duration over which the behavior is evaluated, for those criteria that\n      have a time dimension (for example, <code>NUM_MESSAGES_SENT</code>). For a\n        <code>statisticalThreshhold</code> metric comparison, measurements from all devices are\n      accumulated over this time duration before being used to calculate percentiles, and later,\n      measurements from an individual device are also accumulated over this time duration before\n      being given a percentile rank. Cannot be used with list-based metric datatypes.</p>"}))
    BehaviorCriteria.add_member(:consecutive_datapoints_to_alarm, Smithy::Schema::Shapes::ShapeRef.new(shape: ConsecutiveDatapointsToAlarm, location_name: 'consecutiveDatapointsToAlarm', traits: {"smithy.api#documentation" => "<p>If a device is in violation of the behavior for the specified number of consecutive \n          datapoints, an alarm occurs. If not specified, the default is 1.</p>"}))
    BehaviorCriteria.add_member(:consecutive_datapoints_to_clear, Smithy::Schema::Shapes::ShapeRef.new(shape: ConsecutiveDatapointsToClear, location_name: 'consecutiveDatapointsToClear', traits: {"smithy.api#documentation" => "<p>If an alarm has occurred and the offending device is no longer in violation of the behavior \n          for the specified number of consecutive datapoints, the alarm is cleared. If not specified,\n          the default is 1.</p>"}))
