    CreateJobRequest.add_member(:target_selection, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetSelection, location_name: 'targetSelection', traits: {"smithy.api#documentation" => "<p>Specifies whether the job will continue to run (CONTINUOUS), or will be complete\n            after all those things specified as targets have completed the job (SNAPSHOT). If\n            continuous, the job may also be run on a thing when a change is detected in a target.\n            For example, a job will run on a thing when the thing is added to a target group, even\n            after the job was completed by all things originally in the group.</p>\n         <note>\n            <p>We recommend that you use continuous jobs instead of snapshot jobs for dynamic\n                thing group targets. By using continuous jobs, devices that join the group receive\n                the job execution even after the job has been created.</p>\n         </note>"}))
    CreateJobRequest.add_member(:job_executions_rollout_config, Smithy::Schema::Shapes::ShapeRef.new(shape: JobExecutionsRolloutConfig, location_name: 'jobExecutionsRolloutConfig', traits: {"smithy.api#documentation" => "<p>Allows you to create a staged rollout of the job.</p>"}))
    CreateJobRequest.add_member(:abort_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AbortConfig, location_name: 'abortConfig', traits: {"smithy.api#documentation" => "<p>Allows you to create the criteria to abort a job.</p>"}))
    CreateJobRequest.add_member(:timeout_config, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeoutConfig, location_name: 'timeoutConfig', traits: {"smithy.api#documentation" => "<p>Specifies the amount of time each device has to finish its execution of the job. The\n            timer is started when the job execution status is set to <code>IN_PROGRESS</code>. If\n            the job execution status is not set to another terminal state before the time expires,\n            it will be automatically set to <code>TIMED_OUT</code>.</p>"}))
    CreateJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>Metadata which can be used to manage the job.</p>"}))
    CreateJobRequest.add_member(:namespace_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NamespaceId, location_name: 'namespaceId', traits: {"smithy.api#documentation" => "<p>The namespace used to indicate that a job is a customer-managed job.</p>\n         <p>When you specify a value for this parameter, Amazon Web Services IoT Core sends jobs notifications to\n            MQTT topics that contain the value in the following format.</p>\n         <p>\n            <code>$aws/things/<i>THING_NAME</i>/jobs/<i>JOB_ID</i>/notify-namespace-<i>NAMESPACE_ID</i>/</code>\n         </p>\n         <note>\n            <p>The <code>namespaceId</code> feature is only supported by IoT Greengrass at this time. For\n                more information, see <a href=\"https://docs.aws.amazon.com/greengrass/v2/developerguide/setting-up.html\">Setting up IoT Greengrass core devices.</a>\n            </p>\n         </note>"}))
