    CreateJobRequest.add_member(:document_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: ParameterMap, location_name: 'documentParameters', traits: {"smithy.api#documentation" => "<p>Parameters of an Amazon Web Services managed template that you can specify to create the job\n            document.</p>\n         <note>\n            <p>\n               <code>documentParameters</code> can only be used when creating jobs from Amazon Web Services\n                managed templates. This parameter can't be used with custom job templates or to\n                create jobs from them.</p>\n         </note>"}))
    CreateJobRequest.add_member(:scheduling_config, Smithy::Schema::Shapes::ShapeRef.new(shape: SchedulingConfig, location_name: 'schedulingConfig', traits: {"smithy.api#documentation" => "<p>The configuration that allows you to schedule a job for a future date and time in\n            addition to specifying the end behavior for each job execution.</p>"}))
