    DeleteJobExecutionRequest.add_member(:execution_number, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionNumber, location_name: 'executionNumber', traits: {"smithy.api#documentation" => "<p>The ID of the job execution to be deleted. The <code>executionNumber</code> refers\n            to the execution of a particular job on a particular device.</p>\n         <p>Note that once a job execution is deleted, the <code>executionNumber</code> may be\n            reused by IoT, so be sure you get and use the correct value here.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    DeleteJobExecutionRequest.add_member(:force, Smithy::Schema::Shapes::ShapeRef.new(shape: ForceFlag, location_name: 'force', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>(Optional) When true, you can delete a job execution which is \"IN_PROGRESS\".\n            Otherwise, you can only delete a job execution which is in a terminal state\n            (\"SUCCEEDED\", \"FAILED\", \"REJECTED\", \"REMOVED\" or \"CANCELED\") or an exception will occur.\n            The default is false.</p>\n         <note>\n            <p>Deleting a job execution which is \"IN_PROGRESS\", will cause the device to be\n                unable to access job information or update the job execution status. Use caution and\n                ensure that the device is able to recover to a valid state.</p>\n         </note>", "smithy.api#httpQuery" => "force"}))
    DeleteJobExecutionRequest.add_member(:namespace_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NamespaceId, location_name: 'namespaceId', traits: {"smithy.api#documentation" => "<p>The namespace used to indicate that a job is a customer-managed job.</p>\n         <p>When you specify a value for this parameter, Amazon Web Services IoT Core sends jobs notifications to\n            MQTT topics that contain the value in the following format.</p>\n         <p>\n            <code>$aws/things/<i>THING_NAME</i>/jobs/<i>JOB_ID</i>/notify-namespace-<i>NAMESPACE_ID</i>/</code>\n         </p>\n         <note>\n            <p>The <code>namespaceId</code> feature is only supported by IoT Greengrass at this time. For\n                more information, see <a href=\"https://docs.aws.amazon.com/greengrass/v2/developerguide/setting-up.html\">Setting up IoT Greengrass core devices.</a>\n            </p>\n         </note>", "smithy.api#httpQuery" => "namespaceId"}))
    DeleteJobExecutionRequest.type = Types::DeleteJobExecutionRequest
    DeleteJobRequest.add_member(:job_id, Smithy::Schema::Shapes::ShapeRef.new(shape: JobId, location_name: 'jobId', traits: {"smithy.api#documentation" => "<p>The ID of the job to be deleted.</p>\n         <p>After a job deletion is completed, you may reuse this jobId when you create a new\n            job. However, this is not recommended, and you must ensure that your devices are not\n            using the jobId to refer to the deleted job.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    DeleteJobRequest.add_member(:force, Smithy::Schema::Shapes::ShapeRef.new(shape: ForceFlag, location_name: 'force', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>(Optional) When true, you can delete a job which is \"IN_PROGRESS\". Otherwise, you\n            can only delete a job which is in a terminal state (\"COMPLETED\" or \"CANCELED\") or an\n            exception will occur. The default is false.</p>\n         <note>\n            <p>Deleting a job which is \"IN_PROGRESS\", will cause a device which is executing\n                the job to be unable to access job information or update the job execution status.\n                Use caution and ensure that each device executing a job which is deleted is able to\n                recover to a valid state.</p>\n         </note>", "smithy.api#httpQuery" => "force"}))
