    Job.add_member(:scheduling_config, Smithy::Schema::Shapes::ShapeRef.new(shape: SchedulingConfig, location_name: 'schedulingConfig', traits: {"smithy.api#documentation" => "<p>The configuration that allows you to schedule a job for a future date and time in\n            addition to specifying the end behavior for each job execution.</p>"}))
