    TopicRuleDestination.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: TopicRuleDestinationStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>The status of the topic rule destination. Valid values are:</p>\n         <dl>\n            <dt>IN_PROGRESS</dt>\n            <dd>\n               <p>A topic rule destination was created but has not been confirmed. You can set\n                     <code>status</code> to <code>IN_PROGRESS</code> by calling\n                     <code>UpdateTopicRuleDestination</code>. Calling\n                     <code>UpdateTopicRuleDestination</code> causes a new confirmation challenge to\n                  be sent to your confirmation endpoint.</p>\n            </dd>\n            <dt>ENABLED</dt>\n            <dd>\n               <p>Confirmation was completed, and traffic to this destination is allowed. You can\n                  set <code>status</code> to <code>DISABLED</code> by calling\n                     <code>UpdateTopicRuleDestination</code>.</p>\n            </dd>\n            <dt>DISABLED</dt>\n            <dd>\n               <p>Confirmation was completed, and traffic to this destination is not allowed. You\n                  can set <code>status</code> to <code>ENABLED</code> by calling\n                     <code>UpdateTopicRuleDestination</code>.</p>\n            </dd>\n            <dt>ERROR</dt>\n            <dd>\n               <p>Confirmation could not be completed, for example if the confirmation timed out.\n                  You can call <code>GetTopicRuleDestination</code> for details about the error. You\n                  can set <code>status</code> to <code>IN_PROGRESS</code> by calling\n                     <code>UpdateTopicRuleDestination</code>. Calling\n                     <code>UpdateTopicRuleDestination</code> causes a new confirmation challenge to\n                  be sent to your confirmation endpoint.</p>\n            </dd>\n         </dl>"}))
